"use client";
import { ArtemisScope } from "./artemis-scope";
import type { ArtemisHowItWorksContent } from "./components/how-it-works/content";
import View2 from "./components/how-it-works/variants/03-story-stack";
const variants = {"story-stack":View2};
export type { ArtemisHowItWorksContent, ArtemisHowItWorksLink, ArtemisHowItWorksStep } from "./components/how-it-works/content";
export interface ArtemisHowItWorksProps { className?: string; variant?: "story-stack"; /** The words on the how-it-works section; anything left out keeps the layout's own copy. */ content?: Partial<ArtemisHowItWorksContent>; }
export function ArtemisHowItWorks({ className, variant = "story-stack", content }: ArtemisHowItWorksProps) {const View = variants[variant];return <ArtemisScope className={className}><div className="art:flex art:w-full art:min-w-0 art:flex-col art:items-center"><View content={content}/></div></ArtemisScope>;}

// @zeus-internal
import type { ComponentType } from "react";

/** The words on a link or button, and where it goes. */
export interface ArtemisHowItWorksLink {
  label: string;
  href: string;
}

/** One step of the process. Layouts number the steps in order and draw their own scene for each one. */
export interface ArtemisHowItWorksStep {
  /** A short label over the title, such as "Collect". All layouts. Keep labels unique, since story-stack and card-deck tell steps apart by it. */
  label: string;
  /** The step's title. All layouts. */
  title: string;
  /** A sentence or two under the title. All layouts; card-deck shows two lines of it. */
  description: string;
  /** The step's icon. centered-cards, process-grid, walkthrough and card-deck, which keep their own icon for that slot when you leave this out. */
  icon?: ComponentType<{ className?: string }>;
}

/** The words on an Artemis how-it-works section. Every layout reads this shape, so you can switch layouts and keep them. */
export interface ArtemisHowItWorksContent {
  /** The small pill over the headline. All layouts. */
  badge: string;
  /** The heading. All layouts; process-grid, story-stack, walkthrough and card-deck break it into two lines at the middle word. */
  headline: string;
  /** A line or two beside or under the headline. All layouts. */
  subhead: string;
  /** The button after the steps or beside the subhead. centered-cards, process-grid, story-stack and walkthrough. */
  cta?: ArtemisHowItWorksLink;
  /** The steps, in order. All layouts; three look best, and card-deck's own list has four. */
  steps: ArtemisHowItWorksStep[];
}

"use client";
// @zeus-internal
import { ArrowRight } from "lucide-react";
import { motion, useReducedMotion } from "motion/react";
import { ARTEMIS_EASE_OUT } from "../../../lib/ease";
import { artemisCx } from "../../../lib/utils";
import type { ArtemisHowItWorksContent, ArtemisHowItWorksStep } from "../content";
import { CtaLink } from "./03-story-stack/cta-link";
import { RevealHeading } from "./03-story-stack/heading";
import { CollectScene, DecideScene, DeliverScene } from "./03-story-stack/scenes";
import { StepMarker } from "./03-story-stack/step-marker";
const INSTANT = { duration: 0 } as const;
const defaultSteps: ArtemisHowItWorksStep[] = [
    {
        label: "Collect",
        title: "Start with the full picture",
        description: "Bring customer language, internal context, and the original request together before deciding what to build. Nothing is summarized away too early, so the team can see the evidence behind the brief and return to it when priorities change.",
    },
    {
        label: "Decide",
        title: "Make the next move obvious",
        description: "Turn the shared context into a focused outcome, clear ownership, and a plan the whole team can follow. Make tradeoffs explicit and leave every owner with a next move they can act on without another meeting.",
    },
    {
        label: "Deliver",
        title: "Ship without losing the story",
        description: "Review the final work against the original intent, publish it, and keep the result visible after launch. Connect the shipped version back to the decision that shaped it and leave a useful record for the next release.",
    },
];
const DEFAULT = {
    badge: "A simpler way to work",
    headline: "From scattered context to a confident release.",
    subhead: "Three considered steps keep the original signal connected to every decision that follows.",
    cta: { label: "Explore the process", href: "#" },
    steps: defaultSteps,
} satisfies ArtemisHowItWorksContent;
/** The scene for each slot, in turn; every second step sits on the other side. */
const SCENES = [<CollectScene />, <DecideScene />, <DeliverScene />];
const HEADER_VIEWPORT = { once: true, margin: "-50px" } as const;
const STEP_VIEWPORT = { once: true, margin: "-80px" } as const;
const CTA_VIEWPORT = { once: true, margin: "-40px" } as const;
export default function HowItWorksStoryStack({ content }: { content?: Partial<ArtemisHowItWorksContent> } = {}) {
    const reduce = useReducedMotion();
    const copy = { ...DEFAULT, ...content };
    const words = copy.headline.split(" ");
    const heading = [words.slice(0, Math.floor(words.length / 2)), words.slice(Math.floor(words.length / 2))];
    return (<section className="art:w-full art:overflow-hidden art:bg-background art:px-4 art:py-20 art:text-foreground art:@min-[640px]/artemis:px-6 art:@min-[640px]/artemis:py-24 art:@min-[1024px]/artemis:px-8 art:@min-[1024px]/artemis:py-28">
      <div className="art:mx-auto art:w-full art:max-w-7xl">
        <div className="art:mx-auto art:max-w-4xl art:text-center">
          <motion.span className="art:inline-flex art:rounded-full art:border art:border-border/70 art:bg-background art:px-3 art:py-1.5 art:font-medium art:text-muted-foreground art:text-xs" initial={{ opacity: 0, filter: "blur(5px)", transform: "translate3d(0,8px,0)" }} whileInView={{ opacity: 1, filter: "blur(0px)", transform: "translate3d(0,0,0)" }} viewport={HEADER_VIEWPORT} transition={reduce ? INSTANT : { duration: 0.45, ease: ARTEMIS_EASE_OUT }}>
            {copy.badge}
          </motion.span>
          <RevealHeading lines={heading} className="art:block art:mt-7 art:text-balance art:tracking-[-0.055em] art:text-4xl art:font-medium"/>
          <motion.p className="art:mx-auto art:mt-6 art:max-w-2xl art:text-pretty art:text-muted-foreground art:text-sm art:leading-6 art:@min-[640px]/artemis:text-base art:@min-[640px]/artemis:leading-7" initial={{ opacity: 0, transform: "translate3d(0,10px,0)" }} whileInView={{ opacity: 1, transform: "translate3d(0,0,0)" }} viewport={HEADER_VIEWPORT} transition={reduce ? INSTANT : { duration: 0.5, delay: 0.32, ease: ARTEMIS_EASE_OUT }}>
            {copy.subhead}
          </motion.p>
        </div>

        <div className="art:mt-14 art:space-y-16 art:@min-[640px]/artemis:mt-16 art:@min-[640px]/artemis:space-y-20 art:@min-[1024px]/artemis:space-y-28">
          {copy.steps.map((step, i) => {
            const flip = i % 2 === 1;
            return (<article key={step.label} className="art:grid art:items-center art:gap-8 art:@min-[1024px]/artemis:grid-cols-2 art:@min-[1024px]/artemis:gap-16">
              <motion.div className={artemisCx("art:max-w-xl art:px-1 art:@min-[640px]/artemis:px-4 art:@min-[1024px]/artemis:px-8", flip && "art:@min-[1024px]/artemis:order-2")} initial={{ opacity: 0, filter: "blur(7px)", transform: `translate3d(${flip ? 20 : -20}px,0,0)` }} whileInView={{ opacity: 1, filter: "blur(0px)", transform: "translate3d(0,0,0)" }} viewport={STEP_VIEWPORT} transition={reduce ? INSTANT : { duration: 0.65, ease: ARTEMIS_EASE_OUT }}>
                <StepMarker step={i + 1}/>
                <p className="art:mt-8 art:font-medium art:text-muted-foreground art:text-xs art:uppercase art:tracking-[0.15em]">{step.label}</p>
                <h3 className="art:mt-4 art:max-w-lg art:text-balance art:leading-[1.02] art:tracking-[-0.045em] art:text-xl art:font-medium">{step.title}</h3>
                <p className="art:mt-5 art:max-w-lg art:text-pretty art:text-muted-foreground art:text-sm art:leading-6 art:@min-[640px]/artemis:text-base art:@min-[640px]/artemis:leading-7">
                  {step.description}
                </p>
              </motion.div>
              <motion.div className={artemisCx("art:relative art:min-h-[23rem] art:overflow-hidden art:rounded-3xl art:border art:border-border/70 art:@min-[640px]/artemis:min-h-[28rem]", flip && "art:@min-[1024px]/artemis:order-1")} initial={{ clipPath: flip ? "inset(0% 0% 0% 16%)" : "inset(0% 16% 0% 0%)", opacity: 0.5 }} whileInView={{ clipPath: "inset(0% 0% 0% 0%)", opacity: 1 }} viewport={STEP_VIEWPORT} transition={reduce ? INSTANT : { duration: 0.85, ease: ARTEMIS_EASE_OUT }}>
                {SCENES[i % SCENES.length]}
              </motion.div>
            </article>);
        })}
        </div>

        <motion.div className="art:mt-16 art:flex art:justify-center art:@min-[640px]/artemis:mt-20" initial={{ opacity: 0, transform: "translate3d(0,10px,0)" }} whileInView={{ opacity: 1, transform: "translate3d(0,0,0)" }} viewport={CTA_VIEWPORT} transition={reduce ? INSTANT : { duration: 0.45, ease: ARTEMIS_EASE_OUT }}>
          <CtaLink href={copy.cta.href}>
            {copy.cta.label}
            <ArrowRight className="art:size-4"/>
          </CtaLink>
        </motion.div>
      </div>
    </section>);
}

"use client";
// @zeus-internal
import { motion, useReducedMotion } from "motion/react";
import type { ReactNode } from "react";
import { artemisButtonClasses } from "../../../../foundations/button-classes";
import { ARTEMIS_SPRING_PRESS } from "../../../../lib/ease";
export function CtaLink({ href, children }: {
    href: string;
    children: ReactNode;
}) {
    const reduce = useReducedMotion();
    return (<motion.a className={artemisButtonClasses({ variant: "secondary", className: "art:h-9" })} href={href} tabIndex={0} whileHover={reduce ? undefined : { scale: 1.01 }} whileTap={reduce ? undefined : { scale: 0.98 }} transition={ARTEMIS_SPRING_PRESS}>
      {children}
    </motion.a>);
}

"use client";
// @zeus-internal
import { useRef } from "react";
import { useInView } from "motion/react";
import { ArtemisWordEntrance } from "../../../../lib/word-entrance";
export function RevealHeading({ lines, className }: { lines: string[][]; className: string }) {
  const heading = useRef<HTMLHeadingElement>(null);
  const entered = useInView(heading, { once: true, amount: 0.4 });
  let precedingWords = 0;
  return <h2 ref={heading} className={className}>{lines.map((words, index) => {
    const delay = precedingWords * 0.06;
    precedingWords += words.length;
    return <ArtemisWordEntrance key={index} words={words} stagger={0.06} entered={entered} delay={delay} yOffset="24%"/>;
  })}</h2>;
}

"use client";
// @zeus-internal
import { GrainGradient, MeshGradient, Swirl } from "@paper-design/shaders-react";
import { Check, ClipboardPenLine, LayoutDashboard, type LucideIcon, MessageSquareText, Rocket, UsersRound } from "lucide-react";
import { motion, useReducedMotion } from "motion/react";
import type { ReactNode } from "react";
import { ARTEMIS_EASE_OUT } from "../../../../lib/ease";
const INSTANT = { duration: 0 } as const;
const INNER_VIEWPORT = { once: true, margin: "-70px" } as const;
function Backdrop({ children }: {
    children: ReactNode;
}) {
    return (<div aria-hidden="true" className="art:pointer-events-none art:absolute art:inset-0">
      {children}
      <div className="art:absolute art:inset-0 art:bg-background/12 art:dark:bg-background/52"/>
    </div>);
}
function Stage({ children }: {
    children: ReactNode;
}) {
    return (<div aria-hidden="true" className="art:absolute art:inset-0 art:flex art:items-center art:justify-center art:p-6 art:@min-[640px]/artemis:p-10">
      {children}
    </div>);
}
const SOURCES: Array<{
    icon: LucideIcon;
    label: string;
    x: number;
}> = [
    { icon: MessageSquareText, label: "Customer request", x: -18 },
    { icon: ClipboardPenLine, label: "Original brief", x: 18 },
    { icon: UsersRound, label: "Team context", x: -18 },
];
export function CollectScene() {
    const reduce = useReducedMotion();
    return (<>
      <Backdrop>
        <GrainGradient className="art:h-full art:w-full" speed={0.12} colorBack="#f1d9bf" colors={["#f8dfc8", "#eeb38f", "#d99a7e", "#f3cfa8"]} softness={0.86} intensity={0.5} noise={0.25} shape="corners"/>
      </Backdrop>
      <Stage>
        <div className="art:w-full art:max-w-md art:space-y-3">
          {SOURCES.map(({ icon: Icon, label, x }, i) => (<motion.div key={label} className="art:flex art:items-center art:gap-4 art:rounded-2xl art:border art:border-border/70 art:bg-background/48 art:p-4 art:backdrop-blur-xl art:supports-[backdrop-filter]:bg-background/35" initial={{ opacity: 0, transform: `translate3d(${x}px,0,0)` }} whileInView={{ opacity: 1, transform: "translate3d(0,0,0)" }} viewport={INNER_VIEWPORT} transition={reduce ? INSTANT : { duration: 0.55, delay: i * 0.08, ease: ARTEMIS_EASE_OUT }}>
              <span className="art:grid art:size-10 art:place-items-center art:rounded-full art:bg-muted art:text-muted-foreground">
                <Icon className="art:size-4" strokeWidth={1.7}/>
              </span>
              <span className="art:font-medium art:text-sm">{label}</span>
              <span className="art:ml-auto art:rounded-full art:border art:border-border/70 art:bg-background/35 art:px-2.5 art:py-1 art:text-xs art:backdrop-blur-md">
                Included
              </span>
            </motion.div>))}
        </div>
      </Stage>
    </>);
}
const DECISIONS = ["Define the outcome", "Choose the owner", "Set the next review"];
export function DecideScene() {
    const reduce = useReducedMotion();
    return (<>
      <Backdrop>
        <MeshGradient className="art:h-full art:w-full" speed={0.12} colors={["#dbeafe", "#93c5fd", "#60a5fa", "#d4e6f4"]} distortion={0.48} swirl={0.28} grainMixer={0} grainOverlay={0}/>
      </Backdrop>
      <Stage>
        <motion.div className="art:w-full art:max-w-md art:rounded-3xl art:border art:border-border/70 art:bg-background/48 art:p-5 art:backdrop-blur-xl art:supports-[backdrop-filter]:bg-background/35 art:@min-[640px]/artemis:p-6" initial={{ opacity: 0, transform: "scale(0.975)", filter: "blur(6px)" }} whileInView={{ opacity: 1, transform: "scale(1)", filter: "blur(0px)" }} viewport={INNER_VIEWPORT} transition={reduce ? INSTANT : { duration: 0.65, ease: ARTEMIS_EASE_OUT }}>
          <div className="art:flex art:items-center art:justify-between">
            <div>
              <p className="art:font-medium art:text-muted-foreground art:text-xs art:uppercase art:tracking-[0.14em]">Working session</p>
              <p className="art:mt-2 art:font-semibold art:text-xl art:tracking-[-0.03em]">Make the call together</p>
            </div>
            <span className="art:grid art:size-10 art:place-items-center art:rounded-full art:bg-muted">
              <LayoutDashboard className="art:size-4" strokeWidth={1.7}/>
            </span>
          </div>
          <div className="art:mt-6 art:space-y-2">
            {DECISIONS.map((label, i) => (<motion.div key={label} className="art:flex art:items-center art:gap-3 art:rounded-xl art:border art:border-border/65 art:bg-background/40 art:px-4 art:py-3" initial={{ opacity: 0, transform: "translate3d(0,10px,0)" }} whileInView={{ opacity: 1, transform: "translate3d(0,0,0)" }} viewport={INNER_VIEWPORT} transition={reduce ? INSTANT : { duration: 0.42, delay: 0.18 + i * 0.07, ease: ARTEMIS_EASE_OUT }}>
                <span className="art:grid art:size-6 art:place-items-center art:rounded-full art:bg-foreground art:text-background">
                  <Check className="art:size-3"/>
                </span>
                <span className="art:font-medium art:text-sm">{label}</span>
              </motion.div>))}
          </div>
        </motion.div>
      </Stage>
    </>);
}
export function DeliverScene() {
    const reduce = useReducedMotion();
    return (<>
      <Backdrop>
        <Swirl className="art:h-full art:w-full" speed={0.1} colorBack="#dcebd9" colors={["#eef1cf", "#b7d4b5", "#78a98f"]} bandCount={4} twist={0.1} center={0.2} proportion={0.5} softness={0} noiseFrequency={0.4} noise={0.2}/>
      </Backdrop>
      <Stage>
        <motion.div className="art:w-full art:max-w-md art:rounded-3xl art:border art:border-border/70 art:bg-background/48 art:p-6 art:text-center art:backdrop-blur-xl art:supports-[backdrop-filter]:bg-background/35 art:@min-[640px]/artemis:p-8" initial={{ opacity: 0, filter: "blur(8px)", transform: "translate3d(0,18px,0) scale(0.98)" }} whileInView={{ opacity: 1, filter: "blur(0px)", transform: "translate3d(0,0,0) scale(1)" }} viewport={INNER_VIEWPORT} transition={reduce ? INSTANT : { duration: 0.65, ease: ARTEMIS_EASE_OUT }}>
          <span className="art:mx-auto art:grid art:size-14 art:place-items-center art:rounded-full art:bg-foreground art:text-background">
            <Rocket className="art:size-6" strokeWidth={1.7}/>
          </span>
          <p className="art:mt-5 art:font-semibold art:text-2xl art:tracking-[-0.04em]">The release is live</p>
          <p className="art:mx-auto art:mt-3 art:max-w-xs art:text-pretty art:text-muted-foreground art:text-sm art:leading-6">
            Everyone can see what changed, why it changed, and what happens next.
          </p>
          <div className="art:mt-6 art:flex art:items-center art:justify-center art:gap-2">
            <span className="art:rounded-full art:border art:border-border/70 art:bg-background/35 art:px-3 art:py-1.5 art:font-medium art:text-xs art:backdrop-blur-md">
              Published
            </span>
            <span className="art:rounded-full art:border art:border-border/70 art:bg-background/35 art:px-3 art:py-1.5 art:font-medium art:text-xs art:backdrop-blur-md">
              Shared
            </span>
          </div>
        </motion.div>
      </Stage>
